# Business case. Written by the business, independent of any tool.
id: CP-005
title: An out-of-tolerance thickness measurement holds the coil automatically (Level 2)
process: Quality
subprocess: Measurement at line exit
systems: [L2 (Java desktop), MES]
priority: A
owner: Rolling mill quality (key user)
frequency: daily
preconditions:
  - There is an order in progress in the MES with grade S275JR and a released coil of 3.00 mm × 1250 mm nominal
  - "S275JR specification in the MES: thickness ± 0.15 mm, width −0/+10 mm, flatness ≤ 15 I"
data:
  coil: the released coil of the order
  thickness_mm: 3.25
  width_mm: 1252
  flatness_i: 8
steps:
  - Open the client "Level 2 · Hot strip mill" and press "Measurements"
  - Type the coil in "Coil to measure" and press "Load coil"
  - Enter thickness 3.25, width 1252 and flatness 8 and press "Register measurement"
expected_results:
  - Before measuring, the client shows the thickness limits "2.85 – 3.15 mm"
  - The warning "Measurement out of tolerance" appears with the text "Thickness 3.25 mm outside 2.85–3.15 mm"
  - The coil goes to HOLD with reason "Thickness out of tolerance" without the operator pressing "Hold"
  - The order's produced quantity drops by exactly the coil's weight
data_validation:
  - "MES GET /api/coils/{id}: quality = HOLD, hold_motive = Thickness out of tolerance, measurements[0].result = NOK"
  - "MES GET /api/coils/{id}: events[0].action = HOLD, events[0].operator = MES"
  - "MES GET /api/orders/{order}: produced_t = previous produced − coil weight / 1000"
dependencies:
  needs: an order in progress (CP-001 leaves one after step 4)
----
# What a test agent may know about each system. Most systems in a plant are bought: the agent
# learns them as a new key user would, through their screens and their documented interfaces,
# never through their code. Only the systems we build ourselves expose their source.
#   source: path of its source in this repo (in-house system) or null (black box)
#   access: the ways in, for the agent and for the tests it writes
# Enforced by tools/pipeline/author.sh: the agent works in a sealed copy of the repo that does not
# contain the source of black-box systems, and may not read the original checkout.
# Protected like catalog/ (CODEOWNERS, agent permissions): agents cannot change their own access.
systems:
  ERP:
    name: ERP (Odoo 19, standing in for SAP)
    type: commercial
    source: null
    access: [web screens, documented API (JSON-RPC; BAPI/OData in SAP)]
  L2:
    name: Level 2 client (vendor Java desktop application)
    type: commercial
    source: null
    access: [desktop screens (accessibility tree)]
  MES:
    name: Rolling mill MES (built in-house)
    type: in-house
    source: apps/mes
    access: [web screens, REST API, source code]
# A case with `black_box: true` gets no source at all, in-house systems included (to test a system
# the way an outside party would, or to check that the case can be automated without the code).
----
tests/desktop:
support

tests/desktop/support:
desktop.mjs
// Protected support layer for desktop tests (CODEOWNERS: QA platform).
// Deterministic executor over agent-desktop (OS accessibility tree: AT-SPI / UIA / AX):
// elements are found by role + accessible name on every call (no stale refs, no coordinates).
// Learned limits, Swing via java-atk-wrapper on Linux (agent-desktop 1.2.0), handled here:
//   - JTable rows cannot be selected semantically -> filter to one row, focus table, press Down
//   - JOptionPane dialogs report "offscreen" -> they own keyboard focus; use keys()
//   - AT-SPI bounds are offset by the window frame -> never click by coordinates
import { execFileSync, spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

// How to reach the desktop session: a container locally, plain shell on a desktop VM (instabox).
const EXEC = (process.env.DESKTOP_EXEC ?? "docker exec qa-desktop").split(" ").filter(Boolean);
const sh = (cmd) =>
  execFileSync(EXEC[0], [...EXEC.slice(1), "bash", "-lc", `source ~/.desktop-env 2>/dev/null; ${cmd}`], {
    encoding: "utf8",
    maxBuffer: 64 << 20,
  });
const q = (s) => `'${String(s).replaceAll("'", `'\\''`)}'`;

function ad(args) {
  const out = JSON.parse(sh(`agent-desktop ${args}`));
  if (!out.ok) throw new Error(`agent-desktop ${args.split(" ")[0]}: ${out.error?.message}`);
  return out.data;
}

export function desktop(app, evidenceDir) {
  mkdirSync(evidenceDir, { recursive: true });
  let shot = 0;
  const ref = (role, name, window) => {
    const d = ad(`find --app ${q(app)} --role ${role} --name ${q(name)} ${window ? `--window-id ${q(window)}` : ""}`);
    if (!d.matches?.length) throw new Error(`Cannot find ${role} "${name}" in ${app}`);
    return d.matches[0].ref_id;
  };
  const api = {
    launch(cmd, title, timeoutMs = 30_000) {
      sh(`(${cmd} > /tmp/app.log 2>&1 &)`);
      ad(`wait --window ${q(title)} --app ${q(app)} --timeout ${timeoutMs}`);
    },
    click: (role, name) => ad(`click ${ref(role, name)}`),
    type: (role, name, text) => ad(`type ${ref(role, name)} ${q(text)}`),
    /** Select the only row left in a table (filter first). */
    selectOnlyRow(table) {
      ad(`--headed focus ${ref("table", table)}`);
      ad(`--headed press Down`);
    },
    /** Keyboard into whatever has focus (modal dialogs). */
    keys(text, then = "Return") {
      sh(`xdotool type --delay 15 ${q(text)}${then ? `; xdotool key ${then}` : ""}`);
    },
    window: (title) => ad(`list-windows`).find((w) => w.title === title),
    waitWindowGone(title, timeoutMs = 10_000) {
      const end = Date.now() + timeoutMs;
      while (api.window(title) && Date.now() < end) sh("sleep 0.3");
      if (api.window(title)) throw new Error(`Window "${title}" is still open`);
    },
    /** All visible texts of the app window, in tree order (table cells included). */
    texts: () => {
      const d = ad(`snapshot --app ${q(app)}`);
      const out = [];
      (function walk(n) {
        if (n?.role === "statictext" && n.name) out.push(n.name);
        (n?.children ?? []).forEach(walk);
      })(d.tree);
      return out;
    },
    screenshot(label) {
      const name = `${String(++shot).padStart(2, "0")}-${label.replace(/[^\w-]+/g, "_")}.png`;
      sh(`ffmpeg -loglevel error -y -f x11grab -video_size 1920x1080 -i $DISPLAY -frames:v 1 /tmp/${name}`);
      writeFileSync(join(evidenceDir, name), execFileSync(EXEC[0], [...EXEC.slice(1), "cat", `/tmp/${name}`]));
    },
    /** Video of the whole display while the test runs. Returns stop(). */
    record(file = "video.mp4") {
      const p = spawn(EXEC[0], [...EXEC.slice(1), "bash", "-lc",
        `source ~/.desktop-env; exec ffmpeg -loglevel error -y -f x11grab -framerate 25 -video_size 1920x1080 -i $DISPLAY -pix_fmt yuv420p /tmp/${file}`]);
      return async () => {
        sh(`pkill -INT -f "ffmpeg.*x11grab.*/tmp/${file}" || true`);
        await new Promise((r) => p.on("exit", r));
        writeFileSync(join(evidenceDir, file), execFileSync(EXEC[0], [...EXEC.slice(1), "cat", `/tmp/${file}`], { maxBuffer: 1 << 30 }));
      };
    },
    close: () => sh(`agent-desktop close-app ${q(app)} >/dev/null 2>&1 || pkill -f '[L]2Client' || true`),
  };
  return api;
}

