194	function tx<T>(fn: () => T): T {
195	  db.exec("BEGIN");
196	  try { const r = fn(); db.exec("COMMIT"); return r; } catch (e) { db.exec("ROLLBACK"); throw e; }
197	}
198	function holdCoil(id: number, motive: string, comment: string | null, operator: string | null) {
199	  db.prepare("UPDATE coils SET quality = 'HOLD' WHERE id = ?").run(id);
200	  db.prepare("INSERT INTO quality_events (coil_id, action, motive, comment, operator) VALUES (?, 'HOLD', ?, ?, ?)").run(id, motive, comment, operator);
201	}
202	const operatorOf = (b: any) => String(b?.operator ?? "").trim() || null;
203	
204	app.post("/api/coils/:id/hold", async (c) => {
205	  const body = await c.req.json().catch(() => null);
206	  const k = coilById(c.req.param("id"));
207	  if (!k) return c.json({ error: "not found" }, 404);
208	  const { hold, errors } = parseHold(body);
209	  if (!hold) return c.json({ errors }, 422);
210	  if (k.quality === "HOLD") return c.json({ errors: [`Coil ${k.coil_no} is already held`] }, 409);
211	  tx(() => holdCoil(k.id, hold.motive, hold.comment, operatorOf(body)));
212	  return c.json(coilById(String(k.id)));
213	});
214	
215	app.post("/api/coils/:id/release", async (c) => {
216	  const body = await c.req.json().catch(() => null);
217	  const k = coilById(c.req.param("id"));
218	  if (!k) return c.json({ error: "not found" }, 404);
219	  const { release, errors } = parseRelease(body);
220	  if (!release) return c.json({ errors }, 422);
221	  if (k.quality !== "HOLD") return c.json({ errors: [`Coil ${k.coil_no} is not held`] }, 409);
222	  tx(() => {
223	    db.prepare("UPDATE coils SET quality = 'OK' WHERE id = ?").run(k.id);
224	    db.prepare(`INSERT INTO quality_events (coil_id, action, motive, comment, supervisor, operator) VALUES (?, 'RELEASE', ?, ?, ?, ?)`)
225	      .run(k.id, release.motive, release.comment, release.supervisor, operatorOf(body));
226	  });
227	  return c.json(coilById(String(k.id)));
228	});
229	
230	// A measurement out of tolerance holds the coil automatically (the client only reports what the MES decided).
231	app.post("/api/coils/:id/measurements", async (c) => {
232	  const body = await c.req.json().catch(() => null);
233	  const k = coilById(c.req.param("id"));
234	  if (!k) return c.json({ error: "not found" }, 404);
235	  const limits = coilLimits(k);
236	  if (!limits) return c.json({ errors: [`Grade ${k.grade} has no specification in the MES`] }, 422);
237	  const { m, errors } = parseMeasurement(body);
238	  if (!m) return c.json({ errors }, 422);
239	  const failures = evaluateMeasurement(m, limits);
240	  const held = failures.length > 0 && k.quality === "OK";
241	  const id = tx(() => {
242	    const r = db.prepare(`INSERT INTO measurements (coil_id, thickness_mm, width_mm, flatness_iu, result, detail, operator)
243	      VALUES (?, ?, ?, ?, ?, ?, ?)`).run(k.id, m.thickness_mm, m.width_mm, m.flatness_iu, failures.length ? "NOK" : "OK",
244	      failures.map((f) => f.message).join("; ") || null, operatorOf(body));
245	    if (held) holdCoil(k.id, failures[0].motive, `Automatic hold from measurement: ${failures.map((f) => f.message).join("; ")}`, "MES");
246	    return r.lastInsertRowid;
247	  });
248	  return c.json({
249	    measurement: db.prepare("SELECT * FROM measurements WHERE id = ?").get(id),
250	    ok: failures.length === 0, failures, limits, held, coil: coilById(String(k.id)),
251	  }, 201);
252	});
253	
254	const dayStops = (date: string) => db.prepare(`SELECT * FROM stops WHERE start_at < ? AND end_at > ? ORDER BY start_at`)
255	  .all(`${date}T24:00`, `${date}T00:00`) as any[];
256	app.get("/api/stops", (c) => {
257	  const date = c.req.query("date") ?? "";
258	  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return c.json({ error: "date must be YYYY-MM-DD" }, 422);
259	  return c.json(dayStops(date));
260	});
261	app.post("/api/stops", async (c) => {
262	  const body = await c.req.json().catch(() => null);
263	  const existing = db.prepare("SELECT start_at, end_at FROM stops").all() as any[];
264	  const { stop, errors } = parseStop(body, existing);
265	  if (!stop) return c.json({ errors }, errors.some((e) => e.startsWith("Overlaps")) ? 409 : 422);
266	  const r = db.prepare("INSERT INTO stops (start_at, end_at, reason, comment, operator) VALUES (?, ?, ?, ?, ?)")
267	    .run(stop.start_at, stop.end_at, stop.reason, stop.comment, operatorOf(body));
268	  return c.json(db.prepare("SELECT * FROM stops WHERE id = ?").get(r.lastInsertRowid), 201);
269	});
270	app.get("/api/availability", (c) => {
271	  const date = c.req.query("date") ?? "";
272	  const shift = (c.req.query("shift") ?? "") as ShiftCode;
273	  const w = shiftWindow(date, shift);
274	  if (!w) return c.json({ error: "date YYYY-MM-DD and shift M, T or N" }, 422);
275	  const stops = db.prepare("SELECT start_at, end_at FROM stops WHERE start_at < ? AND end_at > ?").all(w.to, w.from) as any[];
276	  return c.json({ date, shift, shift_name: SHIFTS[shift].name, ...w, ...availability(stops, w), stops: stops.length });
277	});
278	
279	// --- ERP sync loop ---
280	const erp = process.env.ERP_URL
281	  ? new Erp({ url: process.env.ERP_URL, db: process.env.ERP_DB ?? "erp", user: process.env.ERP_USER ?? "", password: process.env.ERP_PASSWORD ?? "" })
282	  : null;
283	let running = false;
284	async function kick() {
285	  if (!erp || running) return;
286	  running = true;
287	  try { await syncOnce(db, erp); } catch (e) { console.error("sync:", (e as Error).message); } finally { running = false; }
288	}
289	if (erp) setInterval(kick, Number(process.env.SYNC_INTERVAL_S ?? 10) * 1000);
290	
291	const port = Number(process.env.PORT ?? 3000);
292	const server = serve({ fetch: app.fetch, port }, () => console.log(`MES on :${port}${erp ? `, ERP ${process.env.ERP_URL}` : ", no ERP"}`));
293	// Longer than clients' pooled-connection idle time (Node default 5 s drops reused connections).
294	Object.assign(server, { keepAliveTimeout: 65_000, headersTimeout: 66_000 });
