1	// Business rules of the MES, kept free of I/O so they are unit-testable.
2	import type { Coil } from "./db.ts";
3	
4	export type CoilInput = {
5	  coil_no: string;
6	  heat_no: string;
7	  weight_kg: number;
8	  thickness_mm: number;
9	  width_mm: number;
10	  quality: "OK" | "HOLD";
11	};
12	
13	// Hot strip mill envelope: anything outside is a typo, not a coil.
14	export const LIMITS = {
15	  weight_kg: [1_000, 40_000],
16	  thickness_mm: [1.2, 25.4],
17	  width_mm: [600, 2_100],
18	} as const;
19	
20	export function parseCoil(form: Record<string, unknown>): { coil?: CoilInput; errors: string[] } {
21	  const errors: string[] = [];
22	  const text = (k: string) => String(form[k] ?? "").trim();
23	  const num = (k: keyof typeof LIMITS, label: string) => {
24	    const v = Number(text(k).replace(",", "."));
25	    const [min, max] = LIMITS[k];
26	    if (!Number.isFinite(v) || v < min || v > max) errors.push(`${label} must be between ${min} and ${max}`);
27	    return v;
28	  };
29	  const coil_no = text("coil_no");
30	  const heat_no = text("heat_no");
31	  if (!/^[A-Z0-9-]{4,20}$/.test(coil_no)) errors.push("Coil no. is not valid");
32	  if (!/^[0-9]{6}$/.test(heat_no)) errors.push("Heat no. must have 6 digits");
33	  const weight_kg = num("weight_kg", "Weight (kg)");
34	  const thickness_mm = num("thickness_mm", "Thickness (mm)");
35	  const width_mm = num("width_mm", "Width (mm)");
36	  const quality = text("quality") === "HOLD" ? "HOLD" : "OK";
37	  return errors.length
38	    ? { errors }
39	    : { coil: { coil_no, heat_no, weight_kg, thickness_mm, width_mm, quality }, errors };
40	}
41	
42	// What the ERP is told was produced: only coils released by quality count.
43	export function producedTonnes(coils: Pick<Coil, "weight_kg" | "quality">[]): number {
44	  const kg = coils.filter((c) => c.quality === "OK").reduce((s, c) => s + c.weight_kg, 0);
45	  return Math.round(kg) / 1000;
46	}
47	
48	// Tonnes always with kg precision: "47.750 t", "1,250.500 t".
49	export function formatTonnes(t: number): string {
50	  return `${t.toLocaleString("en-US", { minimumFractionDigits: 3, maximumFractionDigits: 3, useGrouping: true })} t`;
51	}
52	
53	// Inbound interface contract ERP -> MES (one manufacturing order).
54	export type InboundOrder = {
55	  erp_ref: string;
56	  sale_ref: string | null;
57	  customer: string;
58	  product: string;
59	  grade: string;
60	  qty_t: number;
61	  due_date: string | null;
62	};
63	
64	export function parseInboundOrder(p: any): { order?: InboundOrder; errors: string[] } {
65	  const errors: string[] = [];
66	  const str = (k: string, required = true) => {
67	    const v = p?.[k];
68	    if (v == null || v === "") {
69	      if (required) errors.push(`${k} is required`);
70	      return null;
71	    }
72	    if (typeof v !== "string") errors.push(`${k} must be text`);
73	    return String(v);
74	  };
75	  const erp_ref = str("erp_ref");
76	  const sale_ref = str("sale_ref", false);
77	  const customer = str("customer");
78	  const product = str("product");
79	  const grade = str("grade");
80	  const due_date = str("due_date", false);
81	  const qty_t = p?.qty_t;
82	  if (typeof qty_t !== "number" || !(qty_t > 0)) errors.push("qty_t must be a positive number (tonnes)");
83	  if (due_date && !/^\d{4}-\d{2}-\d{2}$/.test(due_date)) errors.push("due_date must be YYYY-MM-DD");
84	  return errors.length
85	    ? { errors }
86	    : { order: { erp_ref: erp_ref!, sale_ref, customer: customer!, product: product!, grade: grade!, qty_t, due_date }, errors };
87	}
88	
89	// Steel grade from the product name, e.g. "Hot-rolled coil S275JR" -> "S275JR".
90	export function gradeOf(productName: string): string {
91	  return productName.match(/\b(S\d{3}[A-Z0-9+]*|DC0\d|DD1\d)\b/)?.[1] ?? "N/A";
92	}
93	
94	// --- Level 2 (L2 client): quality, measurements, downtime ---
95	
96	// Tolerances per grade. Nominal thickness/width are the coil's own (they come with the order).
97	export type GradeSpec = { grade: string; thickness_tol_mm: number; width_tol_mm: { minus: number; plus: number }; flatness_max_iu: number };
98	export const GRADE_SPECS: GradeSpec[] = [
99	  { grade: "S275JR", thickness_tol_mm: 0.15, width_tol_mm: { minus: 0, plus: 10 }, flatness_max_iu: 15 },
100	  { grade: "S355J2", thickness_tol_mm: 0.12, width_tol_mm: { minus: 0, plus: 10 }, flatness_max_iu: 12 },
101	  { grade: "DD11", thickness_tol_mm: 0.1, width_tol_mm: { minus: 0, plus: 6 }, flatness_max_iu: 10 },
102	];
103	export const gradeSpec = (grade: string) => GRADE_SPECS.find((s) => s.grade === grade);
104	
105	export const HOLD_MOTIVES = ["Flatness defect", "Thickness out of tolerance", "Width out of tolerance", "Surface defect", "Damaged edges"];
106	export const RELEASE_MOTIVES = ["Reinspection passed", "Customer concession", "Measurement error"];
107	export const STOP_REASONS = ["Roll change", "Mechanical failure", "Electrical failure", "Material shortage", "Process adjustment"];
108	// Only a shift supervisor may release a held coil.
109	export const SUPERVISORS: Record<string, string> = { S0412: "A. Morgan", S0587: "J. Reed", S0733: "M. Hale" };
110	
111	type Range = [number, number];
112	export type Limits = { grade: string; thickness_mm: Range; width_mm: Range; flatness_iu: Range };
113	
114	const r3 = (n: number) => Math.round(n * 1000) / 1000;
115	const fmt = (n: number) => n.toLocaleString("en-US", { maximumFractionDigits: 3 });
116	
117	export function coilLimits(coil: { grade: string; thickness_mm: number; width_mm: number }): Limits | null {
118	  const s = gradeSpec(coil.grade);
119	  if (!s) return null;
120	  return {
121	    grade: s.grade,
122	    thickness_mm: [r3(coil.thickness_mm - s.thickness_tol_mm), r3(coil.thickness_mm + s.thickness_tol_mm)],
123	    width_mm: [coil.width_mm - s.width_tol_mm.minus, coil.width_mm + s.width_tol_mm.plus],
124	    flatness_iu: [0, s.flatness_max_iu],
125	  };
126	}
127	
128	export type Measurement = { thickness_mm: number; width_mm: number; flatness_iu: number };
129	const MEASURE_FIELDS = [
130	  { key: "thickness_mm", label: "Thickness", unit: "mm", motive: "Thickness out of tolerance", max: 30 },
131	  { key: "width_mm", label: "Width", unit: "mm", motive: "Width out of tolerance", max: 2500 },
132	  { key: "flatness_iu", label: "Flatness", unit: "I", motive: "Flatness defect", max: 200 },
133	] as const;
134	
135	export function parseMeasurement(p: any): { m?: Measurement; errors: string[] } {
136	  const errors: string[] = [];
137	  const m: Record<string, number> = {};
138	  for (const f of MEASURE_FIELDS) {
139	    const v = Number(String(p?.[f.key] ?? "").trim().replace(",", "."));
140	    if (String(p?.[f.key] ?? "").trim() === "" || !Number.isFinite(v) || v < 0 || v > f.max || (v === 0 && f.key !== "flatness_iu"))
141	      errors.push(`${f.label} (${f.unit}) is not valid`);
