// CP-005 · An out-of-tolerance thickness measurement holds the coil automatically (Level 2).
// Preconditions by MES interfaces (order + released coil), steps on the L2 desktop client,
// validation by MES data. Business values come from catalog/cases/CP-005.yaml.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { parse } from "yaml";
import { desktop } from "./support/desktop.mjs";

const CASE = parse(readFileSync(new URL("../../catalog/cases/CP-005.yaml", import.meta.url), "utf8"));
const MES = process.env.MES_URL ?? "http://127.0.0.1:13000";
const APP = "java";
const MAIN = "Level 2 · Hot strip mill";
const DIALOG = "Measurement out of tolerance";
const { thickness_mm, width_mm, flatness_i } = CASE.data;

// Unique per run: coil numbers are traceability keys.
const tag = Date.now().toString(36).toUpperCase().slice(-5);
const ORDER = `QA-CP005-${tag}`;
const COIL_NO = `CP5-${tag}`;
const COIL_WEIGHT_KG = 24_300;

async function mes(path, init) {
  const r = await fetch(`${MES}${path}`, init);
  const body = await r.json();
  assert.ok(r.ok, `${init?.method ?? "GET"} ${path}: HTTP ${r.status} ${JSON.stringify(body)}`);
  return body;
}

test(`${CASE.id} · ${CASE.title}`, async (t) => {
  // Precondition: an order in progress, grade S275JR, with a released coil of 3.00 mm × 1250 mm nominal.
  const spec = await mes("/api/grades/S275JR");
  assert.equal(spec.thickness_tol_mm, 0.15, "S275JR thickness tolerance in the MES");
  assert.deepEqual(spec.width_tol_mm, { minus: 0, plus: 10 }, "S275JR width tolerance in the MES");
  assert.equal(spec.flatness_max_iu, 15, "S275JR flatness limit in the MES");

  await mes("/api/orders", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ erp_ref: ORDER, customer: "Northline Fabrication Ltd.", product: "Hot-rolled coil S275JR", grade: "S275JR", qty_t: 48.5 }),
  });
  const created = await mes(`/api/orders/${encodeURIComponent(ORDER)}`);
  // The MES has no JSON endpoint for coils: register it through the MES "New coil" form, as the line does.
  const form = await fetch(`${MES}/orders/${created.id}/coils`, {
    method: "POST",
    redirect: "manual",
    body: new URLSearchParams({ coil_no: COIL_NO, heat_no: "512345", weight_kg: String(COIL_WEIGHT_KG), thickness_mm: "3.00", width_mm: "1250", quality: "OK" }),
  });
  assert.equal(form.status, 303, "MES accepted the coil");
  const before = await mes(`/api/orders/${encodeURIComponent(ORDER)}`);
  assert.equal(before.status, "in_progress");
  const coil = before.coils.find((k) => k.coil_no === COIL_NO);
  assert.equal(coil?.quality, "OK", "the coil starts released");

  const ui = desktop(APP, `evidence/desktop/${CASE.id}`);
  ui.close(); // never drive a leftover client instance
  const stop = ui.record();
  try {
    await t.test(CASE.steps[0], () => {
      ui.launch(`l2-client '${MES}'`, MAIN);
      ui.click("switch", "Measurements");
      ui.screenshot("measurements");
    });

    await t.test(CASE.steps[1], () => {
      ui.type("textfield", "Coil to measure", COIL_NO);
      ui.click("button", "Load coil");
      const texts = ui.texts();
      ui.screenshot("coil-loaded");
      assert.ok(texts.includes(`Coil ${COIL_NO} loaded`), `client confirms the coil: ${texts.slice(-3)}`);
      // Expected: before measuring, the client shows the thickness limits.
      assert.ok(texts.includes("2.85 – 3.15 mm"), "thickness limits 2.85 – 3.15 mm on screen");
    });

    await t.test(CASE.steps[2], () => {
      ui.type("textfield", "Measured thickness (mm)", String(thickness_mm));
      ui.type("textfield", "Measured width (mm)", String(width_mm));
      ui.type("textfield", "Measured flatness (I)", String(flatness_i));
      ui.click("button", "Register measurement");
      // Expected: the out-of-tolerance warning, with the failing dimension and its limits.
      const end = Date.now() + 10_000;
      while (!ui.window(DIALOG) && Date.now() < end) {}
      assert.ok(ui.window(DIALOG), `warning "${DIALOG}" appears`);
      const dialog = ui.texts();
      ui.screenshot("out-of-tolerance-warning");
      assert.ok(dialog.some((s) => s.includes("Thickness 3.25 mm outside 2.85–3.15 mm")), `warning text: ${dialog.join(" | ")}`);
      ui.keys("", "Return"); // JOptionPane owns the keyboard focus
      ui.waitWindowGone(DIALOG);
      ui.screenshot("after-warning");
    });
  } finally {
    await stop();
    ui.close();
  }

  // Data validation (MES): automatic HOLD by the MES, NOK measurement, produced quantity drops by the coil weight.
  const k = await mes(`/api/coils/${coil.id}`);
  assert.equal(k.quality, "HOLD");
  assert.equal(k.hold_motive, "Thickness out of tolerance");
  assert.equal(k.measurements[0].result, "NOK");
  assert.equal(k.events[0].action, "HOLD");
  assert.equal(k.events[0].operator, "MES", "held by the MES, not by an operator pressing Hold");
  const after = await mes(`/api/orders/${encodeURIComponent(ORDER)}`);
  assert.equal(after.produced_t, Math.round((before.produced_t - coil.weight_kg / 1000) * 1000) / 1000);
});

